 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    out = [row[:] for row in grid]
    # A diagonal pair launches a straight ray in both directions, stopping at
    # any existing non-background cell or the grid edge.
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if not (0 <= nc < w and grid[r + 1][nc] == color):
                    continue
                directions = ((r, c, -1, -dc), (r + 1, nc, 1, dc))
                open_directions = []
                for sr, sc, dr, step_c in directions:
                    rr, cc = sr + dr, sc + step_c
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        open_directions.append((sr, sc, dr, step_c))
                # Demonstrations extend unambiguously outward from motif ends;
                # when both ends are free the pair is internal/ambiguous.
                if len(open_directions) != 1:
                    continue
                for sr, sc, dr, step_c in open_directions:
                    rr, cc = sr + dr, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += dr
                        cc += step_c
    return out


